{
  "passageId": "information-asymmetry-free-marketplace",
  "items": [
    {
      "id": "R1",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "완전경쟁시장 모델과 현실 시장을 거래 정보의 완전성이라는 같은 기준에서 대비한다."
    },
    {
      "id": "R2",
      "type": "CAUSE",
      "otherName": "",
      "reason": "거래 상대방보다 정보가 부족한 상황이 실제로 역선택 문제로 이어지는 작용을 설명한다."
    },
    {
      "id": "R3",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "정보 비대칭에 따른 역선택 문제에 정부가 법적 시장 개입으로 대응한다."
    },
    {
      "id": "R4",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "공급자에게 정보 제공을 강제하는 조치를 정부의 법적 시장 개입의 구체적 사례로 제시한다."
    },
    {
      "id": "R5",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "현실 시장의 정보 비대칭에 관한 논의를 온라인 상거래 영역으로 넓힌다."
    },
    {
      "id": "R6",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "증가하는 허위·과장 광고의 특성을 이용자가 진위·의도·편향을 판별하기 어렵다는 내용으로 구체화한다."
    },
    {
      "id": "R7",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "인공 지능을 활용한 허위·과장 광고와 정보 비대칭 문제에 생성물 표시 의무로 대응한다."
    },
    {
      "id": "R8",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "생성물 표시 의무를 이미 도입했지만 정보 제공자까지 적용 대상을 확대해야 한다며 현행 조치의 한계를 제시한다."
    },
    {
      "id": "R9",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "생성물 표시 의무를 이미 도입했지만 플랫폼 사업자에게도 부과해야 한다며 현행 조치의 한계를 제시한다."
    },
    {
      "id": "R10",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "표시 의무의 현행 범위와 확대 주장을 정부 개입에 관한 엇갈린 논의라는 일반적 설명으로 정리한다."
    },
    {
      "id": "R11",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "정부 개입에 관한 논의를 온라인 정보 비대칭에서 사회적·정치적 견해 표명으로 확장한다."
    },
    {
      "id": "R12",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "정부 개입 여부에 관한 여러 입장 중 의견 경쟁과 자율 규제를 중시하는 입장을 구체적으로 설명한다."
    },
    {
      "id": "R13",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "정부 개입 여부에 관한 여러 입장 중 의견 경쟁의 한계를 지적하며 공동 규제를 요구하는 입장을 구체적으로 설명한다."
    },
    {
      "id": "R14",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "경제 영역의 완전경쟁시장 모델을 표현과 의견 경쟁을 설명하는 사상의 자유 시장 이론에 가져다 쓴다."
    },
    {
      "id": "R15",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "완전경쟁시장 모델을 상정한다는 이론적 전제가 의견 경쟁으로 표현의 진위와 가치를 결정해야 한다는 주장을 뒷받침한다."
    },
    {
      "id": "R16",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "미국 연방 대법원이 사상의 자유 시장 이론을 받아들여 표현 보호와 플랫폼 자율 규제에 반영한다."
    },
    {
      "id": "R17",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "사상의 자유 시장 이론과 우리나라 헌법 재판소가 표현의 진위와 가치를 의견 경쟁으로 해결해야 한다는 견해를 공유한다."
    },
    {
      "id": "R18",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "비판론이 정보 공급 불균형 아래에서는 의견 경쟁 자체가 불가능하다고 지적하여 사상의 자유 시장 이론의 전제를 문제 삼는다."
    },
    {
      "id": "R19",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "허위·왜곡 정보가 시민의 판단에 쓰이는 위험에 플랫폼과 정부의 공동 규제 강화로 대응한다."
    },
    {
      "id": "R20",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "정책 담당자가 조작된 정보를 시민의 진정한 의견으로 오인할 위험에 공동 규제 강화로 대응한다."
    },
    {
      "id": "R21",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "정보 공급 불균형으로 의견 경쟁이 작동하지 않는 한계에 플랫폼과 정부의 공동 규제라는 대안을 제시한다."
    },
    {
      "id": "R22",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "표현의 자유가 기본권이라는 사실이 규제에 법적 근거를 갖추어야 한다는 판단의 근거가 된다."
    },
    {
      "id": "R23",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "플랫폼의 사전 삭제·차단과 정부의 사후 규제가 공동 규제의 구체적인 시행 방식을 풀어 설명한다."
    },
    {
      "id": "R24",
      "type": "CONDITION",
      "otherName": "",
      "reason": "플랫폼의 사전 자율 규제가 미흡한 경우에 정부의 사후 규제가 이루어져야 한다는 조건을 제시한다."
    },
    {
      "id": "R25",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "비판론이 정보 불균형과 의사 결정 왜곡 위험을 들어 사상의 자유 시장 이론의 의견 경쟁과 자율 규제 구상을 문제 삼는다."
    },
    {
      "id": "R26",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "정부 개입을 둘러싼 이론적 입장 차이가 드러난 구체적 사례로 실명확인 사건을 제시한다."
    },
    {
      "id": "R27",
      "type": "INTERPRETATION",
      "otherName": "",
      "reason": "헌법 재판소 다수 의견이 실명 확인 관련 법률 규정을 헌법적 기준에 따라 위헌이라고 평가한다."
    },
    {
      "id": "R28",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "같은 실명확인 사건을 두고 위헌으로 판단한 다수 의견과 자율적 교정의 어려움을 강조한 소수 의견을 나란히 제시한다."
    },
    {
      "id": "R29",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "헌법 재판소 소수 의견과 비판론이 허위·왜곡 정보의 자율적 교정에는 한계가 있다는 견해를 공유한다."
    },
    {
      "id": "R30",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "플랫폼과 인공 지능 활용의 일상화가 정부 개입 논의를 다시 새겨 보아야 할 시대적 배경으로 제시된다."
    }
  ]
}

